/* Local-only Excel parsing. Only reviewed measurements are persisted to the active profile. */
const importFields={date:'التاريخ',weight:'الوزن كجم',bfr:'دهون %',muscleWeight:'العضلات الهيكلية كجم SMM',totalMuscleMass:'إجمالي العضلات كجم',musclePercent:'عضلات %',fatMass:'كتلة الدهون كجم',leanWeight:'كتلة دون دهون كجم',bmr:'BMR سعرة',bmi:'BMI',visceralFat:'الدهون الحشوية',water:'الماء %',height:'الطول سم'};
const importNorm=x=>String(x??'').toLowerCase().replace(/[\s_()%\/\-]/g,'');
const importAliases={date:['date','testdate','measuredat','التاريخ','تاريخ'],weight:['weight','bodyweight','الوزن','weightkg'],bfr:['bfr','pbf','bodyfatpercentage','دهون','دهونالجسم'],muscleWeight:['smm','skeletalmusclemass'],totalMuscleMass:['musclemass','totalmusclemass'],musclePercent:['عضل','musclepercent'],fatMass:['fatmass','bodyfatmass'],leanWeight:['fatfreemass','leanweight'],bmr:['bmr','basalmetabolicrate'],bmi:['bmi','bodymassindex'],visceralFat:['visceralfat','visceralfatrating','الدهونالحشوية'],water:['رطوبة','water'],height:['height','الطول']};
function importNumber(v){if(v==null||v==='')return null;const s=String(v).replace(/[٠-٩]/g,x=>'٠١٢٣٤٥٦٧٨٩'.indexOf(x)).replace('٫','.').replace(/,(?=\d{3}\b)/g,'');const m=s.match(/-?\d+(?:\.\d+)?/);return m?Number(m[0]):null}
function importDate(v,order='DMY'){if(typeof v==='number'){if(v<20000||v>80000)return null;const d=new Date(Date.UTC(1899,11,30)+Math.floor(v)*86400000).toISOString().slice(0,10);return d<=today()?d:null}const s=String(v||'').trim();let m=s.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/),y,mo,d;if(m){[,y,mo,d]=m}else{m=s.match(/^(\d{1,2})[/.\-](\d{1,2})[/.\-](\d{4})/);if(!m)return null;y=m[3];mo=order==='MDY'?m[1]:m[2];d=order==='MDY'?m[2]:m[1]}const result=`${y}-${String(mo).padStart(2,'0')}-${String(d).padStart(2,'0')}`;return dateValid(result)&&result<=today()?result:null}
async function readBodyWorkbook(file){if(file.size>10000000)throw Error('الحد الأقصى للملف 10 ميجابايت.');if(!/\.xlsx$/i.test(file.name))throw Error('احفظ الملف بصيغة Excel .xlsx ثم ارفعه.');let total=0;const files=fflate.unzipSync(new Uint8Array(await file.arrayBuffer()),{filter:f=>{total+=f.originalSize;if(total>30000000||f.originalSize>15000000)throw Error('الملف أكبر من الحد المسموح بعد فك الضغط.');return /^xl\/(worksheets\/sheet\d+\.xml|sharedStrings.xml|workbook.xml|_rels\/workbook.xml.rels)$/.test(f.name)}}),decode=new TextDecoder(),xml=k=>new DOMParser().parseFromString(decode.decode(files[k]||new Uint8Array()),'text/xml'),text=n=>n?.textContent||'',shared=[...xml('xl/sharedStrings.xml').getElementsByTagName('si')].map(text);const workbook=xml('xl/workbook.xml');if(['1','true'].includes(workbook.getElementsByTagName('workbookPr')[0]?.getAttribute('date1904')))throw Error('هذا الملف يستخدم تاريخ Excel 1904؛ حوّل عمود التاريخ إلى نص YYYY-MM-DD في ملف جديد قبل الاستيراد.');const rels=new Map([...xml('xl/_rels/workbook.xml.rels').getElementsByTagName('Relationship')].map(x=>[x.getAttribute('Id'),x.getAttribute('Target')]));const sheets=[];for(const sheet of workbook.getElementsByTagName('sheet')){let path=rels.get(sheet.getAttribute('r:id'))||'';path=path.startsWith('/')?path.slice(1):'xl/'+path;path=path.replace('xl/../','');if(!files[path])continue;const rows=[];for(const r of xml(path).getElementsByTagName('row')){if(rows.length>=10000||Number(r.getAttribute('r'))>10000)throw Error('الحد الأقصى 10000 صف لكل ورقة.');const row=[];for(const c of r.getElementsByTagName('c')){let col=0;for(const ch of (c.getAttribute('r')||'A').replace(/\d/g,''))col=col*26+ch.charCodeAt(0)-64;if(col>100)continue;let v=text(c.getElementsByTagName('v')[0]);const type=c.getAttribute('t');if(type==='s')v=shared[Number(v)]||'';else if(type==='inlineStr')v=text(c.getElementsByTagName('is')[0]);else if(v!==''&&type!=='str'&&type!=='e')v=Number(v);row[col-1]=v}const ri=Number(r.getAttribute('r'));if(ri>0){while(rows.length<ri-1)rows.push([])}rows.push(row)}sheets.push({name:sheet.getAttribute('name'),rows})}if(!sheets.length)throw Error('لم نعثر على أوراق قياسات قابلة للقراءة.');return sheets}
function bodyImportCandidates(rows,mapping,order,source){const output=[];let skipped=0;const long=rows.some(r=>r[0]==='BodyWeight');if(long){const scans=new Map(),keys={BodyWeight:'weight',FatMass:'fatMass',FatFreeMass:'leanWeight',MuscleMass:'totalMuscleMass',BasalMetabolicRatekJ:'bmr',BodyMassIndex:'bmi',VisceralFatRating:'visceralFat',Height:'height',Age:'age',WaterMass:'waterLiters'};for(const r of rows){if(!keys[r[0]])continue;const date=importDate(r[2],order);if(!date){skipped++;continue}const stamp=String(r[2]),m=scans.get(stamp)||{date,device:'Boditrax',source:'Excel',muscleType:'total'};let val=importNumber(r[1]);if(r[0]==='BasalMetabolicRatekJ'&&val!=null)val=Math.round(val/4.184);m[keys[r[0]]]=val;scans.set(stamp,m)}for(const m of scans.values())if(m.weight){if(m.fatMass!=null){m.bfr=Math.round(m.fatMass/m.weight*10000)/100;m.bfrCalculated=true}output.push(m)}}else for(const row of rows){const m={date:importDate(row[mapping.date],order),device:source,source:'Excel'};for(const k of Object.keys(importFields).filter(k=>k!=='date'))if(mapping[k]>=0){const v=importNumber(row[mapping[k]]);if(v!=null)m[k]=v}if(!m.date||m.weight==null){if(row.some(x=>x!==''&&x!=null))skipped++;continue}output.push(m)}const limits={weight:[25,250],bfr:[2,70],muscleWeight:[1,150],totalMuscleMass:[1,200],musclePercent:[1,100],bmr:[700,3500],height:[100,230],bmi:[10,70],water:[1,100],fatMass:[0,200],leanWeight:[1,250],visceralFat:[0,100]};return {rows:output.filter(m=>{if(!Number.isFinite(m.weight)||m.weight<25||m.weight>250){skipped++;return false}for(const [k,[min,max]]of Object.entries(limits))if(m[k]!=null&&(!Number.isFinite(m[k])||m[k]<min||m[k]>max))m.reviewRequired=true;if(m.fatMass!=null&&m.bfr!=null&&Math.abs(m.fatMass/m.weight*100-m.bfr)>3)m.reviewRequired=true;return true}),skipped}}
const bodyImportDialog=document.createElement('dialog');bodyImportDialog.id='bodyImportDialog';document.body.append(bodyImportDialog);let bodyImportState=null;
function bodyImportEntry(){return `<div class="card"><div class="card-head"><div><h2>استيراد سجل قياسات Excel</h2><p class="sub">إلى ملف ${esc(profileName())} فقط · يدعم Boditrax والميزان وملفات InBody الجدولية.</p></div><button class="button" data-body-import>رفع Excel</button></div><p class="sub">تُقرأ الورقة على جهازك، ثم تراجع التاريخ والأعمدة والقياسات قبل حفظها. بيانات الحسابات والدخول داخل الملف لا تُستورد.</p></div>`}
function showBodyImport(){bodyImportState={profile:activeProfile,sheets:[],preview:[]};bodyImportDialog.innerHTML=`<div class="dialog-head"><h2>استيراد إلى ${esc(profileName())}</h2><button class="icon-button" data-import-close>×</button></div><label class="field">ملف Excel<input id="bodyExcelFile" type="file" accept=".xlsx"></label><p id="bodyImportError" class="danger" role="alert"></p><div id="bodyImportOptions"></div><div id="bodyImportPreview"></div>`;bodyImportDialog.showModal();$('#bodyExcelFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;bodyImportState.sheets=await readBodyWorkbook(file);$('#bodyImportOptions').innerHTML=`<div class="form-grid"><label class="field">الورقة<select id="bodyImportSheet">${bodyImportState.sheets.map((s,i)=>`<option value="${i}">${esc(s.name)}</option>`).join('')}</select></label><label class="field">ترتيب التاريخ<select id="bodyImportDateOrder"><option value="DMY">يوم / شهر / سنة</option><option value="MDY">شهر / يوم / سنة — تصدير Boditrax</option></select></label>${input('importDevice','اسم الجهاز / المصدر','Excel','text',true,'maxlength="80"')}<label class="field">رقم صف العناوين<input id="bodyImportHeader" type="number" min="1" max="10000" value="1"></label></div><div id="bodyImportMapping"></div><button class="button" id="previewBodyImport">معاينة قبل الحفظ</button>`;$('#bodyImportSheet').onchange=mapImportColumns;$('#bodyImportHeader').onchange=()=>mapImportColumns(false);mapImportColumns();$('#previewBodyImport').onclick=previewBodyImport}catch(err){$('#bodyImportError').textContent=err.message}}}
function mapImportColumns(auto=true){const rows=bodyImportState.sheets[Number($('#bodyImportSheet').value)].rows,long=rows.some(r=>r[0]==='BodyWeight');bodyImportState.long=long;if(auto){const i=rows.findIndex(r=>r.some(c=>importAliases.weight.includes(importNorm(c))));$('#bodyImportHeader').value=Math.max(1,i+1);$('#bodyImportDateOrder').value=long?'MDY':'DMY'}const header=rows[Number($('#bodyImportHeader').value)-1]||[];$('#bodyImportMapping').innerHTML=long?'<p class="notice">تم التعرف على تصدير Boditrax. راجع ترتيب الشهر/اليوم. إجمالي العضلات لا يُسجل كعضلات هيكلية SMM.</p>':`<div class="form-grid">${Object.entries(importFields).map(([key,label])=>`<label class="field">${label}<select data-map-field="${key}"><option value="-1">غير موجود</option>${header.map((h,i)=>`<option value="${i}" ${(importAliases[key]||[]).includes(importNorm(h))?'selected':''}>${i+1} · ${esc(h)}</option>`).join('')}</select></label>`).join('')}</div>`;$('#bodyImportPreview').innerHTML=''}
function previewBodyImport(){try{const rows=bodyImportState.sheets[Number($('#bodyImportSheet').value)].rows,map=Object.fromEntries([...bodyImportDialog.querySelectorAll('[data-map-field]')].map(x=>[x.dataset.mapField,Number(x.value)]));if(!bodyImportState.long&&(map.date<0||map.weight<0))throw Error('حدد عمود التاريخ والوزن.');const result=bodyImportCandidates(bodyImportState.long?rows:rows.slice(Number($('#bodyImportHeader').value)),map,$('#bodyImportDateOrder').value,$('#f-importDevice').value.trim()||'Excel');bodyImportState.preview=result.rows;$('#bodyImportError').textContent='';$('#bodyImportPreview').innerHTML=`<p class="notice">${result.rows.length} قياس قابل للاستيراد · ${result.skipped} صف متجاهل. راجع التاريخ والوزن، وألغِ أي صف لا يخص هذا الشخص. القيم غير المعتادة تستلزم المراجعة.</p><div class="table-wrap"><table><thead><tr><th>اختيار</th><th>التاريخ</th><th>الوزن</th><th>دهون %</th><th>SMM</th><th>إجمالي العضلات</th></tr></thead><tbody>${result.rows.map((m,i)=>`<tr><td><input type="checkbox" data-import-row="${i}" ${m.reviewRequired?'':'checked'} aria-label="اختيار قياس ${esc(m.date)}"></td><td>${esc(m.date)}${m.reviewRequired?' ⚠':''}</td><td>${fmt(m.weight)}</td><td>${m.bfr??'—'}</td><td>${m.muscleWeight??'—'}</td><td>${m.totalMuscleMass??'—'}</td></tr>`).join('')}</tbody></table></div><button class="button" id="saveBodyImport">حفظ القياسات المختارة لهذا الملف</button>`;$('#saveBodyImport').onclick=()=>{try{if(activeProfile!==bodyImportState.profile)throw Error('تغير الملف الحالي؛ أعد فتح الاستيراد.');const chosen=[...bodyImportDialog.querySelectorAll('[data-import-row]:checked')].map(el=>bodyImportState.preview[Number(el.dataset.importRow)]),next=structuredClone(data);let added=0;for(const m of chosen){if(next.measurements.some(x=>x.date===m.date&&x.weight===m.weight&&(x.device===m.device||(x.bfr??null)===(m.bfr??null))))continue;next.measurements.push({...m,id:uid()});added++}validate(next);if(!added)throw Error('لا توجد قياسات جديدة مختارة؛ قد تكون مسجلة مسبقًا.');if(commit(next,'تم استيراد '+added+' قياسًا إلى '+profileName()))bodyImportDialog.close()}catch(e){$('#bodyImportError').textContent=e.message}}}catch(e){$('#bodyImportError').textContent=e.message}}
document.addEventListener('click',e=>{if(e.target.closest('[data-body-import]'))showBodyImport();if(e.target.closest('[data-import-close]'))bodyImportDialog.close()});
const bodyBeforeImport=renderBodyCoach;renderBodyCoach=()=>bodyImportEntry()+bodyBeforeImport();const progressBeforeImport=renderProgress;renderProgress=()=>bodyImportEntry()+progressBeforeImport();

bodyImportDialog.addEventListener('change',e=>{if(e.target.closest('#bodyImportOptions')){bodyImportState.preview=[];$('#bodyImportPreview').innerHTML=''}});
